async def parse_target(self, runtime, target_str):
        """A target is a pipeline of a module into zero or more rules, and each
        module and rule can itself be scoped with zero or more module names."""
        if not target_str:
            return []
        if target_str == 'all':
            return self.all_targets(runtime)
        if target_str.startswith('all:'):
            return self.all_targets(runtime, target_str[4:])
        if target_str.startswith('module:'):
            return self.module_targets(runtime, target_str[7:])
        if target_str.startswith('module:'):
            return self.module_targets(runtime, target_str[7:])
        if target_str.startswith('rule:'):
            return self.rule_targets(runtime, target_str[5:])
        return self.rule_targets(runtime, target_str)

